cd /workspace && python3 - <<'EOF'
import json
bad=0; steps_ok=True; n=0
for r in range(8):
    rows=[json.loads(l) for l in open(f'logs/run_001/optimizer_rank_{r}.jsonl')]
    prev=0
    for i,x in enumerate(rows):
        n+=1
        lo,hi=x['optimizer_step_min'],x['optimizer_step_max']
        if lo!=hi:
            bad+=1
            if bad<6: print('RANK',r,'row',i,'min',lo,'max',hi)
        if not (isinstance(lo,float) and lo==float(i+1)):
            steps_ok=False
            if i<3 or i>1757: print('rank',r,'i',i,'lo',lo,'hi',hi)
        if not x.get('finite_gradient'): print('nonfinite',r,i)
        if x.get('loss_scale') is not None: print('loss_scale',r,i,x['loss_scale'])
print('rows',n,'min!=max count',bad,'monotone step==index',steps_ok)
EOF

